// components/styles/graph-button.scss
var graph_button_default = ".graph-button-wrapper {\n  display: flex;\n  align-items: center;\n}\n\n.graph-button {\n  cursor: pointer;\n  padding: 0;\n  position: relative;\n  background: none;\n  border: none;\n  width: 20px;\n  height: 32px;\n  margin: 0;\n  text-align: inherit;\n  flex-shrink: 0;\n\n  & svg {\n    position: absolute;\n    width: 20px;\n    height: 20px;\n    top: calc(50% - 10px);\n    fill: var(--darkgray);\n    stroke: var(--darkgray);\n    transition: opacity 0.1s ease;\n  }\n\n  &:hover svg {\n    fill: var(--dark);\n    stroke: var(--dark);\n  }\n}\n\n.global-graph-outer {\n  position: fixed;\n  z-index: 999999 !important;\n  left: 0;\n  top: 0;\n  width: 100vw;\n  height: 100vh;\n  background-color: var(--light) !important;\n  display: none;\n  overflow: hidden;\n\n  &.active {\n    display: flex !important;\n    align-items: center;\n    justify-content: center;\n  }\n\n  & > .global-graph-container {\n    border: 1px solid var(--lightgray);\n    background-color: var(--light) !important;\n    border-radius: 12px;\n    box-sizing: border-box;\n    position: relative;\n    height: 88vh;\n    width: 88vw;\n    max-width: 1500px;\n    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.18);\n    overflow: hidden;\n\n    @media all and (max-width: 800px) {\n      width: 95%;\n      height: 80vh;\n    }\n  }\n}\n\nbody.global-graph-open {\n  overflow: hidden;\n\n  .domain-grid,\n  .center,\n  .sidebar.right {\n    visibility: hidden !important;\n  }\n\n  .sidebar.left {\n    z-index: 999999 !important;\n  }\n}\n";

